import { Head, Link } from '@inertiajs/react';
import { Banknote, ExternalLink, Package, ShoppingCart, Truck, TriangleAlert } from 'lucide-react';
import VendorLayout from '../../Layouts/VendorLayout';

export default function Dashboard({ stats = {}, recentOrders = [], recentProducts = [], bestSellingProducts = [], lowStockProducts = [] }) {
    return <VendorLayout><Head title="Vendor Dashboard" /><main className="mx-auto w-full max-w-[1440px] space-y-8 p-5 sm:p-8 lg:p-10"><header><p className="text-sm font-semibold text-primary">Selamat datang kembali</p><h1 className="mt-1 font-heading text-2xl font-bold tracking-tight sm:text-3xl">Ringkasan Toko</h1><p className="mt-2 text-sm leading-6 text-secondary sm:text-base">Pantau produk, pesanan, dan penjualan toko Anda.</p></header><section className="grid grid-cols-1 gap-5 sm:grid-cols-2 xl:grid-cols-4" aria-label="Statistik toko"><Stat label="Total Produk" value={stats.products} icon={Package} /><Stat label="Total Pesanan" value={stats.orders} icon={ShoppingCart} /><Stat label="Penjualan Sederhana" value={formatCurrency(stats.sales)} icon={Banknote} /><Stat label="Pesanan Diproses" value={stats.processingOrders} icon={Truck} /></section><section className="grid grid-cols-1 gap-6 xl:grid-cols-12"><OrdersPanel orders={recentOrders} /><ProductsPanel products={recentProducts} /></section><section className="grid grid-cols-1 gap-6 lg:grid-cols-2"><BestSelling products={bestSellingProducts} /><LowStock products={lowStockProducts} /></section></main></VendorLayout>;
}

function Stat({ label, value, icon: Icon }) { return <article className="rounded-xl border border-surface-container-high bg-surface p-5 shadow-sm"><div className="flex items-start justify-between"><span className="text-sm font-medium text-secondary">{label}</span><span className="flex size-10 items-center justify-center rounded-lg bg-surface-container-low text-primary"><Icon size={20} /></span></div><p className="mt-3 break-words font-heading text-2xl font-bold tracking-tight sm:text-3xl">{value ?? 0}</p></article>; }
function OrdersPanel({ orders }) { return <article className="overflow-hidden rounded-xl border border-surface-container-high bg-surface shadow-sm xl:col-span-8"><PanelHeader title="Pesanan Terbaru" action="Lihat Pesanan" disabled />{orders.length ? <div className="overflow-x-auto"><table className="w-full min-w-[680px] text-left text-sm"><thead className="bg-surface-container-low text-xs uppercase tracking-wide text-secondary"><tr>{['No. Pesanan', 'Pembeli', 'Produk', 'Subtotal', 'Status'].map((heading) => <th className="px-4 py-3" key={heading}>{heading}</th>)}</tr></thead><tbody>{orders.map((order) => <tr key={order.id} className="border-t border-surface-container-high"><td className="whitespace-nowrap px-4 py-3.5 font-semibold text-primary">#{order.order_number}</td><td className="px-4 py-3.5">{order.buyer_name}</td><td className="max-w-[220px] truncate px-4 py-3.5">{order.product_name}{order.item_count > 1 ? ` +${order.item_count - 1}` : ''}</td><td className="whitespace-nowrap px-4 py-3.5 font-semibold">{formatCurrency(order.subtotal)}</td><td className="px-4 py-3.5"><Status status={order.order_status} /></td></tr>)}</tbody></table></div> : <Empty label="Belum ada pesanan untuk toko Anda." />}</article>; }
function ProductsPanel({ products }) { return <article className="overflow-hidden rounded-xl border border-surface-container-high bg-surface shadow-sm xl:col-span-4"><PanelHeader title="Produk Terbaru" action="Produk" href="/vendor/products" />{products.length ? <div className="divide-y divide-surface-container-high">{products.map((product) => <ProductRow key={product.id} product={product} />)}</div> : <Empty label="Belum ada produk." />}</article>; }
function ProductRow({ product }) { return <div className="flex items-center gap-3 p-4"><div className="flex size-12 shrink-0 items-center justify-center overflow-hidden rounded-lg border border-surface-container-high bg-surface-container-low text-primary">{product.image_url ? <img src={product.image_url} alt={product.name} className="size-full object-cover" /> : <Package size={20} />}</div><div className="min-w-0 flex-1"><p className="truncate text-sm font-semibold">{product.name}</p><p className="mt-1 text-sm text-secondary">{formatCurrency(product.price)}</p></div><span className="shrink-0 text-xs text-secondary">Stok {product.stock}</span></div>; }
function BestSelling({ products }) { return <article className="rounded-xl border border-surface-container-high bg-surface p-5 shadow-sm"><PanelHeader title="Produk Terlaris" />{products.length ? <div className="divide-y divide-surface-container-high">{products.map((product) => <div className="flex items-center justify-between gap-3 py-3" key={product.id}><div className="min-w-0"><p className="truncate text-sm font-semibold">{product.name}</p><p className="mt-1 text-sm text-secondary">{formatCurrency(product.price)}</p></div><p className="shrink-0 text-right text-sm font-bold">{product.sold_quantity}<span className="block text-xs font-normal text-secondary">terjual</span></p></div>)}</div> : <Empty label="Belum ada penjualan produk." />}</article>; }
function LowStock({ products }) { return <article className="rounded-xl border border-surface-container-high bg-surface p-5 shadow-sm"><div className="flex items-center gap-3"><TriangleAlert className="text-primary" size={20} /><div><h2 className="font-heading text-lg font-bold">Stok Menipis</h2><p className="mt-1 text-sm text-secondary">Produk dengan stok kurang dari 5 unit.</p></div></div>{products.length ? <div className="mt-4 space-y-3">{products.map((product) => <div className="flex items-center justify-between rounded-lg bg-primary-container/10 px-3 py-2.5" key={product.id}><span className="truncate text-sm font-semibold">{product.name}</span><span className="shrink-0 text-sm font-bold text-primary">{product.stock} unit</span></div>)}</div> : <Empty label="Tidak ada produk dengan stok menipis." />}</article>; }
function PanelHeader({ title, action, href, disabled }) { return <header className="flex items-center justify-between gap-3 border-b border-surface-container-high p-5"><h2 className="font-heading text-lg font-bold">{title}</h2>{action && (disabled ? <span className="inline-flex items-center gap-1 text-xs font-semibold text-secondary/50" aria-disabled="true">{action}<ExternalLink size={14} /></span> : <Link className="inline-flex items-center gap-1 text-xs font-semibold text-primary hover:underline focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-primary" href={href}>{action}<ExternalLink size={14} /></Link>)}</header>; }
function Status({ status }) { return <span className="inline-flex rounded-full border border-primary-container/30 bg-primary-container/10 px-2.5 py-1 text-xs font-semibold text-primary">{status === 'processing' ? 'Diproses' : status}</span>; }
function Empty({ label }) { return <p className="p-8 text-center text-sm text-secondary">{label}</p>; }
function formatCurrency(value) { return new Intl.NumberFormat('id-ID', { style: 'currency', currency: 'IDR', maximumFractionDigits: 0 }).format(Number(value ?? 0)); }